# ! [doc = " This module implements declarative macros: old `macro_rules` and the newer"] # ! [doc = " `macro`. Declarative macros are also known as \"macro by example\", and that's"] # ! [doc = " why we call this module `mbe`. For external documentation, prefer the"] # ! [doc = " official terminology: \"declarative macros\"."] use split_decls_genesis :: ourprelude :: * ; pub (crate) mod diagnostics ; pub (crate) mod macro_rules ; mod macro_check ; mod macro_parser ; mod metavar_expr ; mod quoted ; mod transcribe ; use metavar_expr :: MetaVarExpr ; use rustc_ast :: token :: { Delimiter , NonterminalKind , Token , TokenKind } ; use rustc_ast :: tokenstream :: { DelimSpacing , DelimSpan } ; use rustc_macros :: { Decodable , Encodable } ; use rustc_span :: { Ident , Span } ; #[doc = " Contains the sub-token-trees of a \"delimited\" token tree such as `(a b c)`."] #[doc = " The delimiters are not represented explicitly in the `tts` vector."] #[derive (PartialEq , Encodable , Decodable , Debug)] struct Delimited { delim : Delimiter , #[doc = " FIXME: #67062 has details about why this is sub-optimal."] tts : Vec < TokenTree > , } #[derive (PartialEq , Encodable , Decodable , Debug)] struct SequenceRepetition { #[doc = " The sequence of token trees"] tts : Vec < TokenTree > , #[doc = " The optional separator"] separator : Option < Token > , #[doc = " Whether the sequence can be repeated zero (*), or one or more times (+)"] kleene : KleeneToken , #[doc = " The number of `Match`s that appear in the sequence (and subsequences)"] num_captures : usize , } #[derive (Clone , PartialEq , Encodable , Decodable , Debug , Copy)] struct KleeneToken { span : Span , op : KleeneOp , } impl KleeneToken { fn new (op : KleeneOp , span : Span) -> KleeneToken { KleeneToken { span , op } } } #[doc = " A Kleene-style [repetition operator](https://en.wikipedia.org/wiki/Kleene_star)"] #[doc = " for token sequences."] #[derive (Clone , PartialEq , Encodable , Decodable , Debug , Copy)] pub (crate) enum KleeneOp { #[doc = " Kleene star (`*`) for zero or more repetitions"] ZeroOrMore , #[doc = " Kleene plus (`+`) for one or more repetitions"] OneOrMore , #[doc = " Kleene optional (`?`) for zero or one repetitions"] ZeroOrOne , } #[doc = " Similar to `tokenstream::TokenTree`, except that `Sequence`, `MetaVar`, `MetaVarDecl`, and"] #[doc = " `MetaVarExpr` are \"first-class\" token trees. Useful for parsing macros."] #[derive (Debug , PartialEq , Encodable , Decodable)] enum TokenTree { #[doc = " A token. Unlike `tokenstream::TokenTree::Token` this lacks a `Spacing`."] #[doc = " See the comments about `Spacing` in the `transcribe` function."] Token (Token) , #[doc = " A delimited sequence, e.g. `($e:expr)` (RHS) or `{ $e }` (LHS)."] Delimited (DelimSpan , DelimSpacing , Delimited) , #[doc = " A kleene-style repetition sequence, e.g. `$($e:expr)*` (RHS) or `$($e),*` (LHS)."] Sequence (DelimSpan , SequenceRepetition) , #[doc = " e.g., `$var`. The span covers the leading dollar and the ident. (The span within the ident"] #[doc = " only covers the ident, e.g. `var`.)"] MetaVar (Span , Ident) , #[doc = " e.g., `$var:expr`. Only appears on the LHS."] MetaVarDecl { span : Span , #[doc = " Name to bind."] name : Ident , #[doc = " The fragment specifier."] kind : NonterminalKind , } , #[doc = " A meta-variable expression inside `${...}`."] MetaVarExpr (DelimSpan , MetaVarExpr) , } impl TokenTree { #[doc = " Returns `true` if the given token tree is delimited."] fn is_delimited (& self) -> bool { matches ! (* self , TokenTree :: Delimited (..)) } #[doc = " Returns `true` if the given token tree is a token of the given kind."] fn is_token (& self , expected_kind : & TokenKind) -> bool { match self { TokenTree :: Token (Token { kind : actual_kind , .. }) => actual_kind == expected_kind , _ => false , } } #[doc = " Retrieves the `TokenTree`'s span."] fn span (& self) -> Span { match * self { TokenTree :: Token (Token { span , .. }) | TokenTree :: MetaVar (span , _) | TokenTree :: MetaVarDecl { span , .. } => span , TokenTree :: Delimited (span , ..) | TokenTree :: MetaVarExpr (span , _) | TokenTree :: Sequence (span , _) => span . entire () , } } fn token (kind : TokenKind , span : Span) -> TokenTree { TokenTree :: Token (Token :: new (kind , span)) } }